"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type SlideInPrimitiveProps = ComponentProps<typeof motion.div>;

export function SlideInPrimitive({ children, ...props }: SlideInPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0,y: 28}}
      animate={{opacity: 1,y: 0}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
